package com.gtalee.covert;
import java.awt.*; import java.awt.event.*; import java.io.*; import javax.swing.*;
public final class FramePatchComposeTool extends JFrame { private static String lastInputPath=""; private static String lastOutputPath=""; private JTextField input=new JTextField(28), output=new JTextField(28); private JSpinner threshold=new JSpinner(new SpinnerNumberModel(8,0,255,1)), min=new JSpinner(new SpinnerNumberModel(1,1,100000,1)), size=new JSpinner(new SpinnerNumberModel(64,1,512,1)); public FramePatchComposeTool(){input.setText(lastInputPath); output.setText(lastOutputPath); setTitle("帧差补丁转换");setDefaultCloseOperation(JFrame.DISPOSE_ON_CLOSE); JPanel f=new JPanel(new GridLayout(0,1)); f.add(row("输入图片目录",input,true)); f.add(row("输出目录",output,false)); JPanel opts=new JPanel(new FlowLayout(FlowLayout.LEFT)); opts.add(new JLabel("差异阈值"));opts.add(threshold);opts.add(new JLabel("最小差异像素"));opts.add(min);opts.add(new JLabel("补丁最大尺寸"));opts.add(size);f.add(opts); add(f,BorderLayout.CENTER); JButton run=new JButton("开始转换并验证");run.addActionListener(new ActionListener(){public void actionPerformed(ActionEvent e){run();}});add(run,BorderLayout.SOUTH);setSize(760,220);setLocationRelativeTo(null);}
 private JPanel row(String label,final JTextField field,final boolean dir){JPanel p=new JPanel(new FlowLayout(FlowLayout.LEFT));p.add(new JLabel(label));p.add(field);JButton b=new JButton("选择...");b.addActionListener(new ActionListener(){public void actionPerformed(ActionEvent e){JFileChooser c=new JFileChooser(field.getText());c.setFileSelectionMode(dir?JFileChooser.DIRECTORIES_ONLY:JFileChooser.DIRECTORIES_ONLY);if(c.showOpenDialog(FramePatchComposeTool.this)==JFileChooser.APPROVE_OPTION){field.setText(c.getSelectedFile().getAbsolutePath()); if(dir)lastInputPath=field.getText(); else lastOutputPath=field.getText();}}});p.add(b);return p;}
 private void run(){try{File in=new File(input.getText().trim()),out=new File(output.getText().trim());FramePatchComposeBuilder.Result r=FramePatchComposeBuilder.build(in,out,((Integer)threshold.getValue()).intValue(),0,((Integer)min.getValue()).intValue(),((Integer)size.getValue()).intValue());JOptionPane.showMessageDialog(this,"完成："+r.frameCount+"帧，生成"+r.patchCount+"个图块\n配置文件："+new File(out,"frame_patches.compose.properties"));}catch(Exception e){JOptionPane.showMessageDialog(this,e.getMessage(),"转换失败",JOptionPane.ERROR_MESSAGE);}}
}